return function(args, ctx)
  local r = ctx.workspace.list_dir({ path = args.path })
  if r.error ~= nil then return { response = { path = args.path, error = r.error } } end
  return { response = { path = r.path, entries = r.entries, truncated = r.truncated } }
end

return function(args, ctx)
  local r = ctx.workspace.read({ path = args.path })
  if r.error ~= nil then return { response = { path = args.path, error = r.error } } end
  return { response = { path = r.path, content = r.content, truncated = r.truncated } }
end

return function(args, ctx)
  local r = ctx.workspace.grep({ pattern = args.pattern, path = args.path, case_insensitive = args.case_insensitive })
  if r.error ~= nil then return { response = { error = r.error } } end
  return { response = { pattern = r.pattern, matches = r.matches, truncated = r.truncated } }
end

